  check:'<path d="m5 12 4 4L19 6"/>',
  shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',
  school:'<path d="m3 8 9-5 9 5M5 9v11h14V9M9 20v-5h6v5M9 10h.01M15 10h.01"/>',
  points:'<path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4-4.6-4.5 6.4-.9Z"/>',
